import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatTimestamp } from "helpers/time_helpers"

export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" }, timestamp: String }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: this.#description
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }

  // The server sends the raw timestamp and we turn it into words, exactly like
  // the page does, so the stamp reads the same on both sides of the bridge.
  get #description() {
    if (this.hasTimestampValue) {
      return formatTimestamp(this.timestampValue, "date")
    }

    return this.bridgeElement.bridgeAttribute("description")
  }
}
